const escape = (text:string)=>text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')
const compiled=templates.map(([en,es])=>({regex:new RegExp('^'+en.split(/\{\d+\}/).map(escape).join('([\\s\\S]*?)')+'$'),es,slots:[...en.matchAll(/\{(\d+)\}/g)].map(m=>Number(m[1]))}))
export function tradeVisualCopy(value:string,language:string,depth=0):string {
  if (language!=='es'||depth>5) return value
  const trimmed=value.trim()
  const exact=tradeVisualSpanish[trimmed]??coreUiCopy(trimmed,language)
  if (exact!==trimmed) return value.replace(trimmed,exact)
  // Only recognized pricing descriptions use this grammar; names and user notes are preserved.
  if (/^(dynasty|redraft)\s*·/i.test(trimmed)) return trimmed.split('·').map(token=>tradeVisualCopy(token.trim(),language,depth+1)).join(' · ')
  for (const entry of compiled) {
    const match=entry.regex.exec(value)??entry.regex.exec(trimmed)
    if (!match) continue
    const vars=new Map(entry.slots.map((slot,i)=>[slot,match[i+1]]))
    return entry.es.replace(/\{(\d+)\}/g,(_,slot)=>tradeVisualCopy(vars.get(Number(slot))??'',language,depth+1))
  }
  return value
}
